input.content:
workspace "Parcel Tracker" "A parcel delivery tracking platform" {
    model {
        customer = person "Customer" "Looks up the status of their parcels on the platform."

        parcelTracker = softwareSystem "Parcel Tracker" "The parcel delivery tracking platform, owned and operated by our company." {
            webPortal = container "Web Portal" "Where customers look up shipments. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Web application"
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Service"
            database = container "Database" "Stores shipments and dispatch records." "Database" "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "Sends customer notification emails on behalf of the platform. Operated by a different organization." "External"

        customer -> webPortal "Looks up the status of their parcels" "HTTPS/JSON"
        webPortal -> database "Stores and retrieves shipments" "SQL"
        dispatchService -> database "Stores and retrieves dispatch records" "SQL"
        dispatchService -> emailProvider "Sends customer notification emails" "SMTP"
    }

    views {
        systemContext parcelTracker "SystemContext" {
            include *
            autoLayout
            title "System Context for Parcel Tracker"
        }

        container parcelTracker "Containers" {
            include *
            autoLayout
            title "Containers for Parcel Tracker"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
                background #438DD5
                color #ffffff
            }
        }
    }

    configuration {
        scope softwaresystem
    }
}

